BEGIN;
UPDATE public.config SET value='true' WHERE key='multi_tenant_enabled';
INSERT INTO auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data)
VALUES ('ce8f8da2-0e18-4200-bb52-977aac215332','mcp-rollback-test@example.invalid',now(),'{}','{}');
SELECT set_config('request.jwt.claims','{"sub":"ce8f8da2-0e18-4200-bb52-977aac215332","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT public.tenant_onboard('MCP operações teste rollback');
RESET ROLE;
INSERT INTO auth.sessions(id,user_id) VALUES('a202a202-1111-4111-8111-222222222222','ce8f8da2-0e18-4200-bb52-977aac215332');
INSERT INTO crm_mcp.clients(client_id,resource,can_write,is_active) VALUES('test-crm-operations','https://test.example/mcp',true,true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','ce8f8da2-0e18-4200-bb52-977aac215332','role','authenticated','client_id','test-crm-operations','aud','https://test.example/mcp','session_id','a202a202-1111-4111-8111-222222222222','app_metadata',(SELECT raw_app_meta_data FROM auth.users WHERE id='ce8f8da2-0e18-4200-bb52-977aac215332'))::text,true);

RESET ROLE;
DO $$ DECLARE tid uuid:=public.get_tenant_id(); member uuid; l uuid; a uuid; s uuid; t uuid; d uuid; p uuid; st uuid; target uuid; r jsonb; rid uuid:=gen_random_uuid(); ts integer; BEGIN
 SELECT id INTO member FROM team_members WHERE auth_user_id=auth.uid() AND tenant_id=tid;
 INSERT INTO leads(tenant_id,name) VALUES(tid,'History QA') RETURNING id INTO l;
 INSERT INTO agents_registry(tenant_id,slug,display_name,system_prompt,provider,model,is_active,created_by,responsible_user_id) VALUES(tid,'history-qa','History QA','Prompt anterior seguro de teste','openai','test',false,member,member) RETURNING id INTO a;
 INSERT INTO agents_sessions(tenant_id,agent_id,user_id,channel,playground_context) VALUES(tid,a,member,'playground',jsonb_build_object('lead_id',l)) RETURNING id INTO s;
 INSERT INTO agents_messages(tenant_id,session_id,role,content,tool_calls) VALUES(tid,s,'assistant','Vou agendar','[{"name":"schedule_meeting","arguments":{"day":"tomorrow"}}]');
 INSERT INTO agents_messages(tenant_id,session_id,role,content,tool_call_id) VALUES(tid,s,'tool','{"ok":true,"activity_id":"test"}','call1');
 r:=public.mcp_history('messages',p_id=>s);IF jsonb_array_length(r->'items')<>2 THEN RAISE EXCEPTION 'Mensagens ausentes'; END IF;
 r:=public.mcp_history('conversations',p_lead_id=>l);IF jsonb_array_length(r->'items')<>1 THEN RAISE EXCEPTION 'Conversa não encontrada'; END IF;
 r:=public.mcp_history('agent',p_agent_id=>a);IF r->>'system_prompt'<>'Prompt anterior seguro de teste' THEN RAISE EXCEPTION 'Prompt ausente'; END IF;ts:=(r->>'version')::integer;
 r:=public.mcp_agent_edit(a,rid,ts,'{"system_prompt":"Prompt novo com instruções revisadas"}');
 IF public.mcp_agent_edit(a,rid,ts,'{"system_prompt":"Prompt novo com instruções revisadas"}')<>r THEN RAISE EXCEPTION 'Replay falhou'; END IF;
 BEGIN PERFORM public.mcp_agent_edit(a,gen_random_uuid(),ts,'{"system_prompt":"Outra alteração concorrente de teste"}');RAISE EXCEPTION 'Conflito ignorado';EXCEPTION WHEN serialization_failure THEN NULL;END;
 t:=public.agent_trace_record(a,s,'{"system_prompt":"Prompt efetivo do teste","access_token":"secret-value","tools":[]}');
 PERFORM public.agent_trace_record(a,s,p_trace_id=>t,p_result=>'{"status":"success","text":"OK"}');
 r:=public.mcp_history('trace',p_id=>t);IF r::text LIKE '%secret-value%' OR r->'request'->>'system_prompt'<>'Prompt efetivo do teste' THEN RAISE EXCEPTION 'Trace inseguro/incompleto'; END IF;
 r:=public.mcp_history('traces',p_id=>s);IF jsonb_array_length(r->'items')<>1 THEN RAISE EXCEPTION 'Trace não encontrado';END IF;
 r:=public.mcp_history('context',p_lead_id=>l);IF r->'context'->'contact'->>'id'<>l::text THEN RAISE EXCEPTION 'Contexto falhou'; END IF;
 INSERT INTO sales_pipelines(tenant_id,name) VALUES(tid,'History QA') RETURNING id INTO p;
 INSERT INTO sales_pipeline_stages(tenant_id,pipeline_id,name,position) VALUES(tid,p,'Novo',0) RETURNING id INTO st;
 INSERT INTO sales_pipeline_stages(tenant_id,pipeline_id,name,position) VALUES(tid,p,'Reunião Agendada',1) RETURNING id INTO target;
 INSERT INTO deals(tenant_id,lead_id,title,pipeline_id,pipeline_stage_id,status) VALUES(tid,l,'History QA',p,st,'negotiation') RETURNING id INTO d;
 UPDATE agents_sessions SET playground_context=playground_context||jsonb_build_object('deal_id',d) WHERE id=s;
 SELECT version INTO ts FROM agents_registry WHERE id=a;
 PERFORM public.mcp_agent_edit(a,gen_random_uuid(),ts,jsonb_build_object('meeting_stage_id',target));
 INSERT INTO company_activities(tenant_id,lead_id,name,task_type,scheduled_at,metadata) VALUES(tid,l,'History QA','meeting',now()+interval '1 day',jsonb_build_object('agent_id',a,'session_id',s));
 IF (SELECT pipeline_stage_id FROM deals WHERE id=d)<>target THEN RAISE EXCEPTION 'Agendamento não moveu etapa'; END IF;
 UPDATE deals SET pipeline_stage_id=st WHERE id=d;
 r:=public.agent_schedule_meeting(l,a,member,now()+interval '2 days',30,'Teste scheduler',NULL,s);
 IF r->>'ok'<>'true' OR (SELECT pipeline_stage_id FROM deals WHERE id=d)<>target THEN RAISE EXCEPTION 'Scheduler real falhou';END IF;
 UPDATE deals SET pipeline_stage_id=st WHERE id=d;
 r:=public.agent_schedule_meeting(l,a,member,now()+interval '2 days 10 minutes',30,'Conflito',NULL,s);
 IF r->>'ok'<>'false' OR (SELECT pipeline_stage_id FROM deals WHERE id=d)<>st THEN RAISE EXCEPTION 'Conflito moveu etapa';END IF;
 r:=public.mcp_history('timeline',p_deal_id=>d);IF jsonb_array_length(r->'items')<3 THEN RAISE EXCEPTION 'Timeline incompleta'; END IF;
 r:=public.mcp_history('timeline',p_deal_id=>d,p_limit=>1);IF r->>'next_offset'<>'1' THEN RAISE EXCEPTION 'Paginação falhou';END IF;
 BEGIN PERFORM public.mcp_history('messages',p_id=>'11111111-1111-4111-8111-111111111111');RAISE EXCEPTION 'Sessão alheia aceita';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.mcp_history('timeline',p_lead_id=>'11111111-1111-4111-8111-111111111111');RAISE EXCEPTION 'Lead alheio aceito';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE team_members SET role='sdr' WHERE id=member;
 BEGIN PERFORM public.mcp_history('agent',p_agent_id=>a);RAISE EXCEPTION 'SDR leu prompt admin';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.mcp_agent_edit(a,gen_random_uuid(),0,'{"is_active":true}');RAISE EXCEPTION 'SDR editou';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
SET LOCAL ROLE authenticated;
DO $$ BEGIN
 BEGIN PERFORM public.agent_trace_record(gen_random_uuid(),gen_random_uuid(),'{}');RAISE EXCEPTION 'Cliente escreveu trace';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM 1 FROM crm_mcp.agent_traces;RAISE EXCEPTION 'Cliente leu tabela privada';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
ROLLBACK;
